suppressPackageStartupMessages(library(survival))
root<-normalizePath('260925_Re',winslash='/');src<-file.path(root,'data/processed/tcga_nnls_survival_20260926_145356');out<-file.path(root,'runs',paste0('tcga_NNLS_compartment_cox_',format(Sys.time(),'%Y%m%d_%H%M%S')));dir.create(out)
d<-read.csv(file.path(src,'patient_compartment_survival.csv'));stopifnot(!anyDuplicated(d$patient_id),all(d$event %in% c(0,1)),all(d$time_months>0));d$age10<-d$age_years/10;x<-toupper(trimws(d$stage));stage<-rep(NA_character_,length(x));for(k in c('I','II','III','IV'))stage[grepl(paste0('^STAGE ',k,'[ABC]?$'),x)]<-k;d$stage_group<-factor(stage,levels=c('I','II','III','IV'));d$PAM50<-factor(d$Subtype_mRNA)
comp<-c('malignant_epithelial','normal_epithelial','endothelial','CAF','PVL','B_plasma','T_NK','myeloid');results<-list();phs<-list();logs<-character();selections<-list()
for(k in comp){
 for(model in if(k=='B_plasma')c('age_stage','age_stage_PAM50') else 'age_stage'){
  vars<-c(k,'age10','stage_group',if(model=='age_stage_PAM50')'PAM50');keep<-complete.cases(d[,vars]);dd<-droplevels(d[keep,]);center<-mean(dd[[k]]);spread<-sd(dd[[k]]);dd$comp_z<-(dd[[k]]-center)/spread;label<-paste(k,model,sep='_');selections[[label]]<-data.frame(patient_id=d$patient_id,compartment=k,model=model,included=keep)
  if(!is.finite(spread)||spread==0){logs<-c(logs,paste(label,'zero variance; not fit'));next}
  form<-as.formula(paste('Surv(time_months,event) ~ comp_z+age10+stage_group',if(model=='age_stage_PAM50')'+PAM50' else ''))
  fit<-withCallingHandlers(coxph(form,data=dd,x=TRUE,y=TRUE,model=TRUE,ties='efron'),warning=function(w){logs<<-c(logs,paste(label,conditionMessage(w)));invokeRestart('muffleWarning')});sm<-summary(fit);ph<-cox.zph(fit,transform='km');co<-sm$coefficients['comp_z',];ci<-sm$conf.int['comp_z',]
  results[[label]]<-data.frame(compartment=k,model=model,n=nrow(dd),events=sum(dd$event),HR_per_SD=ci['exp(coef)'],CI_low=ci['lower .95'],CI_high=ci['upper .95'],p=co['Pr(>|z|)'],exposure_mean=center,exposure_SD=spread,zero_fraction=mean(dd[[k]]==0),PH_exposure_p=ph$table['comp_z','p'],PH_global_p=ph$table['GLOBAL','p'])
  tab<-as.data.frame(ph$table);tab$term<-rownames(tab);tab$compartment<-k;tab$model<-model;phs[[label]]<-tab
  saveRDS(list(fit=fit,ph=ph,patient_ids=dd$patient_id,exposure_center=center,exposure_SD=spread),file.path(out,paste0(label,'.rds')))
  write.csv(data.frame(patient_id=dd$patient_id,linear_predictor=predict(fit,type='lp')),file.path(out,paste0(label,'_in_sample_lp.csv')),row.names=FALSE)
  if(k=='B_plasma'){
   png(file.path(out,paste0(label,'_PH.png')),width=1200,height=700,res=130);plot(ph,var=1);dev.off()
  }
 }
}
res<-do.call(rbind,results);res$BH_q_eight_compartment_family<-NA_real_;idx<-res$model=='age_stage';res$BH_q_eight_compartment_family[idx]<-p.adjust(res$p[idx],method='BH',n=8);write.csv(res,file.path(out,'compartment_cox_results.csv'),row.names=FALSE);write.csv(do.call(rbind,phs),file.path(out,'PH_tests.csv'),row.names=FALSE);write.csv(do.call(rbind,selections),file.path(out,'all_model_patient_selection.csv'),row.names=FALSE)
# Cutpoints use exposure quantiles only. Never split tied zero estimates by patient rank.
cuts<-unname(quantile(d$B_plasma,c(1/3,2/3)));write.csv(data.frame(quantile=c(1/3,2/3),cutpoint=cuts),file.path(out,'Bplasma_quantile_cutpoints.csv'),row.names=FALSE)
if(length(unique(cuts))==2){
 d$group<-cut(d$B_plasma,breaks=c(-Inf,cuts,Inf),labels=c('lower','middle','upper'),include.lowest=TRUE);fit<-survfit(Surv(time_months,event)~group,data=d);lr<-survdiff(Surv(time_months,event)~group,data=d);write.csv(data.frame(group=names(table(d$group)),n=as.vector(table(d$group))),file.path(out,'Bplasma_group_sizes.csv'),row.names=FALSE);write.csv(data.frame(chisq=lr$chisq,df=length(lr$n)-1,p=pchisq(lr$chisq,length(lr$n)-1,lower.tail=FALSE)),file.path(out,'Bplasma_global_logrank.csv'),row.names=FALSE);saveRDS(list(fit=fit,logrank=lr,patient_ids=d$patient_id,groups=d$group),file.path(out,'Bplasma_KM.rds'))
 png(file.path(out,'Bplasma_exploratory_KM.png'),width=1200,height=800,res=130);plot(fit,col=c('#316B9D','#777777','#C45345'),lwd=2,xlab='Months',ylab='Overall survival',conf.int=TRUE);legend('bottomleft',legend=paste(names(table(d$group)),'n=',as.vector(table(d$group))),col=c('#316B9D','#777777','#C45345'),lwd=2);title('NNLS proxy groups; unequal sizes from tied zero estimates');dev.off()
} else logs<-c(logs,'Quantile cutpoints coincide: KM grouping skipped; tied zero values not arbitrarily split.')
writeLines(c('Exploratory TCGA associations with NNLS RNA-contribution proxies, not original BayesPrism clinical effects.', 'Primary family: eight one-compartment-at-a-time age/stage-adjusted Cox models; BH over all eight. Effects per complete-case SD.', 'B/plasma additional PAM50-adjusted sensitivity is reported separately, not included in the eight-test family. Complete cases, no covariate selection by p value.', 'PH diagnostics are unadjusted model checks. Persistent compositional, tumor subtype and measurement confounding prohibit causal or treatment-benefit inference.', 'No external METABRIC replication of these exposure effects, no predictive survival accuracy, no optimization of cutpoints. KM groups can be unequal because of exact zeros.',paste('Input directory:',src)),file.path(out,'scope_and_config.txt'));writeLines(logs,file.path(out,'warnings.txt'));writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt'));writeLines('{"status":"exploratory_TCGA_NNLS_Cox_completed","canonical_BayesPrism_replication":false}',file.path(out,'COMPLETE.json'));print(res);cat(out,'\n')
